return {h=5,w=54,cr=255,hc=20,bh=70,gr="medium-slow",eg={"plant"},st={45,50,55,75,65,30},ab={{34,0},{50,1}},genus={en="Weed Pokémon",es="Pokémon Hierbajo",pt="Pokémon Erva Daninha"},flavor={en={[1]="During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.",[2]="During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.",[3]="It may be mistaken for a clump of weeds. If you try to yank it out of the ground, it shrieks horribly.",[4]="Awakened by moonlight, it roams actively at night. In the day, it stays quietly underground.",[5]="If exposed to moonlight, it starts to move. It roams far and wide at night to scatter its seeds.",[6]="During the day, it stays in the cold underground to avoid the sun. It grows by bathing in moonlight.",[7]="During the daytime, ODDISH buries itself in soil to absorb nutrients from the ground using its entire body. The more fertile the soil, the glossier its leaves become.",[8]="ODDISH searches for fertile, nutrient-rich soil, then plants itself. During the daytime, while it is planted, this Pokémon’s feet are thought to change shape and become similar to the roots of trees.",[9]="This Pokémon grows by absorbing moonlight. During the daytime, it buries itself in the ground, leaving only its leaves exposed to avoid detection by its enemies.",[10]="Its scientific name is “Oddium Wanderus.” At night, it is said to walk nearly 1,000 feet on its two roots.",[11]="During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.",[12]="It often plants its root feet in the ground during the day and sows seeds as it walks about at night.",[13]="It often plants its root feet in the ground during the day and sows seeds as it walks about at night.",[14]="It often plants its root feet in the ground during the day and sows seeds as it walks about at night.",[15]="Awakened by moonlight, it roams actively at night. In the day, it stays quietly underground.",[16]="If exposed to moonlight, it starts to move. It roams far and wide at night to scatter its seeds.",[17]="It often plants its root feet in the ground during the day and sows seeds as it walks about at night.",[18]="It often plants its root feet in the ground during the day and sows seeds as it walks about at night.",[21]="It often plants its root feet in the ground during the day and sows seeds as it walks about at night.",[22]="It often plants its root feet in the ground during the day and sows seeds as it walks about at night.",[23]="During the day, it stays in the cold underground to avoid the sun. It grows by bathing in moonlight.",[24]="Its scientific name is “Oddium Wanderus.” At night, it is said to walk nearly 1,000 feet on its two roots.",[25]="During the daytime, Oddish buries itself in soil to absorb nutrients from the ground using its entire body. The more fertile the soil, the glossier its leaves become.",[26]="Oddish searches for fertile, nutrient-rich soil, then plants itself. During the daytime, while it is planted, this Pokémon’s feet are thought to change shape and become similar to the roots of trees.",[31]="It may be mistaken for a clump of weeds. If you try to yank it out of the ground, it shrieks horribly.",[32]="It may be mistaken for a clump of weeds. If you try to yank it out of the ground, it shrieks horribly.",[33]="If exposed to moonlight, it starts to move. It roams far and wide at night to scatter its seeds.",[34]="During the day, it stays in the cold underground to avoid the sun. It grows by bathing in moonlight."},es={[23]="Durante el día, se agazapa en el frío subsuelo huyendo del sol. La luz de la luna le hace crecer mucho.",[24]="Su nombre científico es “Oddium Wanderus”. Se dice que de noche puede llegar a desplazarse hasta 300 m con sus dos raíces.",[25]="Durante el día, Oddish se entierra en el suelo para absorber nutrientes valiéndose de todo el cuerpo. Cuanto más fértil sea el suelo, mayor brillo tendrá en las hojas.",[26]="Oddish busca los suelos fértiles y ricos en nutrientes para plantarse en la tierra. Durante el día, se cree que le cambia la forma de los pies y se le empiezan a parecer a las raíces de los árboles.",[31]="En ocasiones lo confunden con una mala hierba y, al tratar de arrancarlo, profiere unos gritos escalofriantes.",[32]="En ocasiones lo confunden con una mala hierba y, al tratar de arrancarlo, profiere unos gritos escalofriantes.",[33]="Se mueve al exponerse a la luz de la luna. Merodea por la noche para esparcir sus semillas.",[34]="Durante el día, se agazapa en el frío subsuelo huyendo del sol. La luz de la luna le hace crecer."},pt="Durante o dia, fica no subsolo frio para evitar o sol. Cresce banhando-se na luz da lua."},evo={{s=43},{s=44,from=43,c={{t="level-up",lv=21}}},{s=45,from=44,c={{t="use-item",item=85}}},{s=182,from=44,c={{t="use-item",item=80}}}},moves={[1]={1,71,15,77,17,78,19,79,24,51,33,80,46,76},[2]={1,71,15,77,17,78,19,79,24,51,33,80,46,76},[3]={1,71,7,230,14,77,16,78,18,79,23,51,32,236,39,80},[4]={1,71,7,230,14,77,16,78,18,79,23,51,32,236,39,80},[5]={1,71,7,230,14,77,16,78,18,79,23,51,32,236,39,80},[6]={1,71,7,230,14,77,16,78,18,79,23,51,32,236,39,80},[7]={1,71,7,230,14,77,16,78,18,79,23,51,32,236,39,80},[8]={1,71,5,230,9,51,13,77,15,78,17,79,21,72,25,381,29,363,33,236,37,202,41,80},[9]={1,71,5,230,9,51,13,77,15,78,17,79,21,72,25,381,29,363,33,236,37,202,41,80},[10]={1,71,5,230,9,51,13,77,15,78,17,79,21,72,25,381,29,363,33,236,37,202,41,80},[11]={1,71,5,230,9,51,13,77,15,78,17,79,21,72,25,381,29,363,33,236,37,202,41,80},[12]={1,71,7,230,14,77,16,78,18,79,23,51,32,236,39,80},[13]={1,71,7,230,14,77,16,78,18,79,23,51,32,236,39,80},[14]={1,71,5,230,9,51,13,77,15,78,17,79,21,72,25,381,29,363,33,236,37,202,41,80},[15]={1,71,5,230,9,51,13,77,15,78,17,79,21,72,25,381,29,363,33,236,37,202,41,80,45,580},[16]={1,71,5,230,9,51,13,77,14,78,15,79,19,72,23,381,27,236,31,202,35,92,39,363,43,585,47,580,51,80},[17]={1,71,1,74,5,230,9,51